import { z } from 'zod';

const EnvSchema = z.object({
  NODE_ENV: z.enum(['development', 'test', 'production']).default('development'),
  HOST: z.string().default('0.0.0.0'),
  PORT: z.coerce.number().int().min(0).max(65_535).default(3000),
  LOG_LEVEL: z.enum(['fatal', 'error', 'warn', 'info', 'debug', 'trace']).default('info'),
  LOG_PRETTY: z.coerce.boolean().default(false),

  REDIS_URL: z.string().default('redis://127.0.0.1:6379'),
  REDIS_KEY_PREFIX: z.string().default('cart:'),
  REDIS_CONNECT_TIMEOUT_MS: z.coerce.number().int().min(50).default(3_000),
  REDIS_COMMAND_TIMEOUT_MS: z.coerce.number().int().min(50).default(2_000),
  REDIS_MAX_RETRIES: z.coerce.number().int().min(0).default(2),
  REDIS_TLS: z.coerce.boolean().default(false),

  CART_TTL_SECONDS: z.coerce.number().int().min(60).default(60 * 60 * 24 * 14),
  CART_MAX_ITEMS: z.coerce.number().int().min(1).default(200),
  CART_MAX_QUANTITY_PER_LINE: z.coerce.number().int().min(1).default(99),
  CART_MAX_ACTIVE_PER_USER: z.coerce.number().int().min(1).default(5),

  CACHE_TTL_MS: z.coerce.number().int().min(0).default(2_000),
  CACHE_MAX_ENTRIES: z.coerce.number().int().min(1).default(10_000),

  RATE_LIMIT_ENABLED: z.coerce.boolean().default(true),
  RATE_LIMIT_CAPACITY: z.coerce.number().int().min(1).default(120),
  RATE_LIMIT_REFILL_PER_SECOND: z.coerce.number().int().min(1).default(20),

  IDEMPOTENCY_TTL_SECONDS: z.coerce.number().int().min(1).default(60 * 60 * 24),

  SHIPPING_FLAT_CENTS: z.coerce.number().int().min(0).default(499),
  FREE_SHIPPING_THRESHOLD_CENTS: z.coerce.number().int().min(0).default(5_000),
  TAX_BPS: z.coerce.number().int().min(0).max(10_000).default(2_100),

  PROMO_RULES: z.string().default(
    '{"WELCOME10":{"type":"percent","bps":1000,"maxDiscountCents":2000},"SAVE5":{"type":"fixed","amountCents":500,"minSubtotalCents":3000}}',
  ),

  JWT_SECRET: z.string().min(8).default('dev-secret-change-me'),
  JWT_ISSUER: z.string().default('carrito-escalable'),

  CATALOG_MODE: z.enum(['memory', 'http']).default('memory'),
  CATALOG_URL: z.string().default(''),
  CATALOG_TIMEOUT_MS: z.coerce.number().int().min(50).default(1_500),

  WORKER_CONSUMER_GROUP: z.string().default('cart-events'),
  WORKER_CONSUMER_NAME: z.string().default('worker-1'),
  WORKER_BATCH_SIZE: z.coerce.number().int().min(1).default(50),
  WORKER_BLOCK_MS: z.coerce.number().int().min(1).default(2_000),

  OUTBOX_MAX_LEN: z.coerce.number().int().min(1).default(100_000),
  EVENTS_STREAM_MAX_LEN: z.coerce.number().int().min(1).default(100_000),
});

export type PromoRule =
  | { type: 'percent'; bps: number; maxDiscountCents?: number; minSubtotalCents?: number }
  | { type: 'fixed'; amountCents: number; minSubtotalCents?: number };

export interface PricingRules {
  shippingFlatCents: number;
  freeShippingThresholdCents: number;
  taxBps: number;
  promos: Record<string, PromoRule>;
  limits: {
    maxItems: number;
    maxQuantityPerLine: number;
  };
}

export interface AppConfig {
  env: 'development' | 'test' | 'production';
  host: string;
  port: number;
  logLevel: string;
  logPretty: boolean;
  redis: {
    url: string;
    keyPrefix: string;
    connectTimeoutMs: number;
    commandTimeoutMs: number;
    maxRetries: number;
    tls: boolean;
  };
  cart: {
    ttlSeconds: number;
    maxItems: number;
    maxQuantityPerLine: number;
    maxActivePerUser: number;
  };
  cache: {
    ttlMs: number;
    maxEntries: number;
  };
  rateLimit: {
    enabled: boolean;
    capacity: number;
    refillPerSecond: number;
  };
  idempotencyTtlSeconds: number;
  pricing: PricingRules;
  auth: {
    secret: string;
    issuer: string;
  };
  catalog: {
    mode: 'memory' | 'http';
    url: string;
    timeoutMs: number;
  };
  worker: {
    consumerGroup: string;
    consumerName: string;
    batchSize: number;
    blockMs: number;
  };
  events: {
    streamMaxLen: number;
    outboxMaxLen: number;
  };
}

function parsePromos(raw: string): Record<string, PromoRule> {
  try {
    const parsed = JSON.parse(raw) as Record<string, PromoRule>;
    if (!parsed || typeof parsed !== 'object') return {};
    return parsed;
  } catch {
    throw new Error('PROMO_RULES no es JSON válido');
  }
}

export function loadConfig(env: NodeJS.ProcessEnv = process.env): AppConfig {
  const parsed = EnvSchema.safeParse(env);
  if (!parsed.success) {
    const issues = parsed.error.issues.map((i) => `  - ${i.path.join('.')}: ${i.message}`).join('\n');
    throw new Error(`Configuración inválida:\n${issues}`);
  }
  const e = parsed.data;

  if (e.NODE_ENV === 'production' && e.JWT_SECRET === 'dev-secret-change-me') {
    throw new Error('JWT_SECRET por defecto no permitido en producción');
  }

  return {
    env: e.NODE_ENV,
    host: e.HOST,
    port: e.PORT,
    logLevel: e.LOG_LEVEL,
    logPretty: e.LOG_PRETTY,
    redis: {
      url: e.REDIS_URL,
      keyPrefix: e.REDIS_KEY_PREFIX,
      connectTimeoutMs: e.REDIS_CONNECT_TIMEOUT_MS,
      commandTimeoutMs: e.REDIS_COMMAND_TIMEOUT_MS,
      maxRetries: e.REDIS_MAX_RETRIES,
      tls: e.REDIS_TLS,
    },
    cart: {
      ttlSeconds: e.CART_TTL_SECONDS,
      maxItems: e.CART_MAX_ITEMS,
      maxQuantityPerLine: e.CART_MAX_QUANTITY_PER_LINE,
      maxActivePerUser: e.CART_ACTIVE_PER_USER,
    },
    cache: {
      ttlMs: e.CACHE_TTL_MS,
      maxEntries: e.CACHE_MAX_ENTRIES,
    },
    rateLimit: {
      enabled: e.RATE_LIMIT_ENABLED,
      capacity: e.RATE_LIMIT_CAPACITY,
      refillPerSecond: e.RATE_LIMIT_REFILL_PER_SECOND,
    },
    idempotencyTtlSeconds: e.IDEMPOTENCY_TTL_SECONDS,
    pricing: {
      shippingFlatCents: e.SHIPPING_FLAT_CENTS,
      freeShippingThresholdCents: e.FREE_SHIPPING_THRESHOLD_CENTS,
      taxBps: e.TAX_BPS,
      promos: parsePromos(e.PROMO_RULES),
      limits: {
        maxItems: e.CART_MAX_ITEMS,
        maxQuantityPerLine: e.CART_MAX_QUANTITY_PER_LINE,
      },
    },
    auth: {
      secret: e.JWT_SECRET,
      issuer: e.JWT_ISSUER,
    },
    catalog: {
      mode: e.CATALOG_MODE,
      url: e.CATALOG_URL,
      timeoutMs: e.CATALOG_TIMEOUT_MS,
    },
    worker: {
      consumerGroup: e.WORKER_CONSUMER_GROUP,
      consumerName: e.WORKER_CONSUMER_NAME,
      batchSize: e.WORKER_BATCH_SIZE,
      blockMs: e.WORKER_BLOCK_MS,
    },
    events: {
      streamMaxLen: e.EVENTS_STREAM_MAX_LEN,
      outboxMaxLen: e.OUTBOX_MAX_LEN,
    },
  };
}

export type Currency = 'EUR' | 'USD' | 'GBP';

export const ZERO: Readonly<Record<Currency, number>> = Object.freeze({
  EUR: 0,
  USD: 0,
  GBP: 0,
});

/**
 * Todo el dinero del dominio se expresa en unidades menores (céntimos) como
 * enteros. Nunca se usan floats para dinero: evita errores de redondeo y
 * mantiene paridad exacta entre TypeScript y el script Lua que replica el
 * cálculo en Redis.
 */
export function assertMinorUnits(value: number, field = 'amount'): number {
  if (!Number.isInteger(value)) {
    throw new RangeError(`${field} debe ser un entero en unidades menores (céntimos)`);
  }
  return value;
}

export function clamp(value: number, min: number, max: number): number {
  if (value < min) return min;
  if (value > max) return max;
  return value;
}

/** Aplica un porcentaje en puntos basicos (basis points) redondeando hacia abajo. */
export function applyBps(amount: number, bps: number): number {
  if (bps <= 0) return 0;
  return Math.floor((amount * bps) / 10_000);
}

export function formatMoney(amount: number, currency: Currency): string {
  const symbol = currency === 'EUR' ? '€' : currency === 'USD' ? '$' : '£';
  return `${symbol}${(amount / 100).toFixed(2)}`;
}

/**
 * Errores de dominio. Cada uno lleva un código estable (`code`) que se expone
 * en la respuesta HTTP para que los clientes puedan reaccionar sin parsear
 * mensajes, y un estado HTTP asociado.
 */
export type ErrorCode =
  | 'CART_NOT_FOUND'
  | 'CART_VERSION_CONFLICT'
  | 'CART_ALREADY_CHECKED_OUT'
  | 'INVALID_QUANTITY'
  | 'CART_LIMIT_EXCEEDED'
  | 'PRODUCT_NOT_FOUND'
  | 'PRODUCT_INACTIVE'
  | 'OUT_OF_STOCK'
  | 'PROMO_NOT_FOUND'
  | 'PROMO_NOT_APPLICABLE'
  | 'INVALID_PAYLOAD'
  | 'UNAUTHORIZED'
  | 'FORBIDDEN'
  | 'RATE_LIMITED'
  | 'IDEMPOTENCY_IN_PROGRESS'
  | 'INTERNAL_ERROR';

export class DomainError extends Error {
  readonly code: ErrorCode;
  readonly statusCode: number;
  readonly details: Record<string, unknown> | undefined;

  constructor(
    code: ErrorCode,
    message: string,
    statusCode: number,
    details?: Record<string, unknown>,
  ) {
    super(message);
    this.name = new.target.name;
    this.code = code;
    this.statusCode = statusCode;
    this.details = details;
    Error.captureStackTrace?.(this, new.target);
  }

  toJSON(): Record<string, unknown> {
    return { code: this.code, message: this.message, details: this.details };
  }
}

export class CartNotFoundError extends DomainError {
  constructor(cartId: string) {
    super('CART_NOT_FOUND', `El carrito ${cartId} no existe`, 404, { cartId });
  }
}

export class CartVersionConflictError extends DomainError {
  constructor(cartId: string, expectedVersion: number, actualVersion: number) {
    super(
      'CART_VERSION_CONFLICT',
      'El carrito ha cambiado desde la última lectura; vuelve a intentarlo con la versión actual',
      409,
      { cartId, expectedVersion, actualVersion },
    );
  }
}

export class InvalidQuantityError extends DomainError {
  constructor(quantity: number, max: number) {
    super('INVALID_QUANTITY', `Cantidad inválida: ${quantity} (máximo ${max})`, 400, {
      quantity,
      max,
    });
  }
}

export class CartLimitExceededError extends DomainError {
  constructor(maxItems: number) {
    super('CART_LIMIT_EXCEEDED', `El carrito no puede superar ${maxItems} líneas`, 409, {
      maxItems,
    });
  }
}

export class ProductNotFoundError extends DomainError {
  constructor(productId: string) {
    super('PRODUCT_NOT_FOUND', `El producto ${productId} no existe en el catálogo`, 404, {
      productId,
    });
  }
}

export class ProductInactiveError extends DomainError {
  constructor(productId: string) {
    super('PRODUCT_INACTIVE', `El producto ${productId} no está disponible`, 409, {
      productId,
    });
  }
}

export class OutOfStockError extends DomainError {
  constructor(sku: string, requested: number, available: number) {
    super('OUT_OF_STOCK', `Stock insuficiente para ${sku}`, 409, { sku, requested, available });
  }
}

export class PromoNotFoundError extends DomainError {
  constructor(code: string) {
    super('PROMO_NOT_FOUND', `El código promocional ${code} no existe`, 404, { code });
  }
}

export class PromoNotApplicableError extends DomainError {
  constructor(code: string, reason: string) {
    super('PROMO_NOT_APPLICABLE', `El código ${code} no es aplicable: ${reason}`, 422, {
      code,
      reason,
    });
  }
}

export class UnauthorizedError extends DomainError {
  constructor(message = 'Credenciales ausentes o inválidas') {
    super('UNAUTHORIZED', message, 401);
  }
}

export class ForbiddenError extends DomainError {
  constructor(message = 'No tienes permisos sobre este recurso') {
    super('FORBIDDEN', message, 403);
  }
}

export class RateLimitedError extends DomainError {
  constructor(retryAfterSeconds: number) {
    super('RATE_LIMITED', 'Demasiadas peticiones, inténtalo más tarde', 429, {
      retryAfterSeconds,
    });
  }
}

export class InvalidPayloadError extends DomainError {
  constructor(message: string, details?: Record<string, unknown>) {
    super('INVALID_PAYLOAD', message, 400, details);
  }
}

import { createHash } from 'node:crypto';
import type { Currency } from './money.js';

export interface VolumeBreak {
  minQuantity: number;
  discountBps: number;
}

export interface CatalogProduct {
  productId: string;
  variantId: string | null;
  sku: string;
  name: string;
  unitPriceCents: number;
  currency: Currency;
  active: boolean;
  stock: number;
  volumeBreaks: VolumeBreak[];
  metadata: Record<string, string>;
}

export interface CatalogLookup {
  productId: string;
  variantId?: string | null;
}

export interface Catalog {
  getProduct(lookup: CatalogLookup): Promise<CatalogProduct | null>;
}

/**
 * Identificador de línea determinista: el mismo producto+variante siempre cae
 * en la misma línea, lo que permite que las mutaciones concurrentes sobre
 * "la misma referencia" converjan sin duplicados.
 */
export function computeLineId(productId: string, variantId: string | null): string {
  return createHash('sha256')
    .update(`${productId}::${variantId ?? ''}`)
    .digest('hex')
    .slice(0, 24);
}

export function resolveVolumeBreak(breaks: VolumeBreak[], quantity: number): number {
  let bps = 0;
  for (const br of breaks) {
    if (quantity >= br.minQuantity && br.discountBps > bps) {
      bps = br.discountBps;
    }
  }
  return bps;
}

import type { Currency } from './money.js';

export type CartStatus = 'active' | 'checked_out' | 'abandoned';

export interface CartItem {
  lineId: string;
  productId: string;
  variantId: string | null;
  sku: string;
  name: string;
  /** Precio unitario en unidades menores (céntimos). */
  unitPriceCents: number;
  quantity: number;
  /** Descuento de volumen aplicable a la línea, en basis points. */
  discountBps: number;
  /** Descuento de la línea ya aplicado, en unidades menores. */
  discountCents: number;
  /** Descuento de cupón prorrateado a la línea, en unidades menores. */
  promoCents: number;
  /** Total de la línea: (precio * cantidad) - descuentos. */
  lineTotalCents: number;
  /** Reglas de volumen serializadas para poder recalcular en Lua. */
  volumeBreaks: Array<{ minQuantity: number; discountBps: number }>;
  metadata: Record<string, string>;
}

export interface CartTotals {
  currency: Currency;
  subtotalCents: number;
  discountCents: number;
  promoCents: number;
  shippingCents: number;
  taxCents: number;
  totalCents: number;
  itemCount: number;
}

export interface Cart {
  id: string;
  ownerId: string | null;
  sessionId: string | null;
  currency: Currency;
  status: CartStatus;
  items: CartItem[];
  promoCodes: string[];
  totals: CartTotals;
  /** Versión monotonica; se incrementa en cada mutación aceptada. */
  version: number;
  createdAt: string;
  updatedAt: string;
  expiresAt: string;
}

export type CartMutation =
  | { kind: 'add_item'; item: CartItem }
  | { kind: 'set_quantity'; lineId: string; quantity: number }
  | { kind: 'remove_item'; lineId: string }
  | { kind: 'clear' }
  | { kind: 'apply_promo'; code: string }
  | { kind: 'remove_promo'; code: string }
  | { kind: 'checkout' };

export type MutationOutcome =
  | { status: 'ok'; cart: Cart }
  | { status: 'not_found' }
  | { status: 'conflict'; current: Cart }
  | { status: 'invalid'; code: string; message: string; details?: Record<string, unknown> };

export function emptyTotals(currency: Currency): CartTotals {
  return {
    currency,
    subtotalCents: 0,
    discountCents: 0,
    promoCents: 0,
    shippingCents: 0,
    taxCents: 0,
    totalCents: 0,
    itemCount: 0,
  };
}

export function itemCount(items: CartItem[]): number {
  let total = 0;
  for (const item of items) total += item.quantity;
  return total;
}

import type { CartItem, CartTotals } from './cart.js';
import type { PromoRule } from '../config.js';
import { applyBps } from './money.js';

export interface PricingInput {
  items: CartItem[];
  promoCodes: string[];
  currency: CartTotals['currency'];
  shippingFlatCents: number;
  freeShippingThresholdCents: number;
  taxBps: number;
  promos: Record<string, PromoRule>;
}

/**
 * Motor de precios determinista. Es la única fuente de verdad de los totales
 * y está replicado 1:1 en `src/infrastructure/lua/cart.lua` (mismo orden de
 * operaciones, misma aritmética entera) para que la mutación atómica dentro
 * de Redis y el recálculo en el proceso de aplicación den exactamente el
 * mismo resultado. `test/unit/pricing.parity.test.ts` verifica la paridad.
 */
export function computeTotals(input: PricingInput): CartTotals {
  const { items, promoCodes, currency, promos } = input;

  let subtotalCents = 0;
  let discountCents = 0;
  let netCents = 0;

  const lineNet: number[] = [];

  for (const item of items) {
    const gross = item.unitPriceCents * item.quantity;
    const volumeDiscount = applyBps(gross, item.discountBps);
    subtotalCents += gross;
    discountCents += volumeDiscount;
    const net = gross - volumeDiscount;
    netCents += net;
    lineNet.push(net);
  }

  // Los cupones se aplican sobre el importe ya descontado por volumen, en el
  // orden en que se añadieron al carrito.
  let promoCents = 0;
  let remaining = netCents;
  for (const code of promoCodes) {
    const rule = promos[code];
    if (!rule) continue;
    let amount = 0;
    if (rule.type === 'percent') {
      if (rule.minSubtotalCents !== undefined && remaining < rule.minSubtotalCents) continue;
      amount = applyBps(remaining, rule.bps);
      if (rule.maxDiscountCents !== undefined && amount > rule.maxDiscountCents) {
        amount = rule.maxDiscountCents;
      }
    } else {
      if (rule.minSubtotalCents !== undefined && remaining < rule.minSubtotalCents) continue;
      amount = rule.amountCents;
    }
    if (amount > remaining) amount = remaining;
    if (amount <= 0) continue;
    promoCents += amount;
    remaining -= amount;
  }

  const netAfterPromoCents = netCents - promoCents;
  const shippingCents =
    netAfterPromoCents === 0
      ? 0
      : netAfterPromoCents >= input.freeShippingThresholdCents
        ? 0
        : input.shippingFlatCents;
  const taxCents = applyBps(netAfterPromoCents + shippingCents, input.taxBps);
  const totalCents = netAfterPromoCents + shippingCents + taxCents;

  let itemCount = 0;
  for (const item of items) itemCount += item.quantity;

  return {
    currency,
    subtotalCents,
    discountCents,
    promoCents,
    shippingCents,
    taxCents,
    totalCents,
    itemCount,
  };
}

/**
 * Prorratea el descuento de cupón entre las líneas de forma determinista
 * (resto al último importe), de modo que la suma de las líneas coincide
 * exactamente con el total del carrito sin perder ni crear céntimos.
 */
export function proratePromo(items: CartItem[], totals: CartTotals): CartItem[] {
  const netBase = totals.subtotalCents - totals.discountCents;
  if (totals.promoCents === 0 || netBase <= 0) {
    return items.map((item) => ({
      ...item,
      promoCents: 0,
      lineTotalCents: item.unitPriceCents * item.quantity - item.discountCents,
    }));
  }

  const result: CartItem[] = [];
  let assigned = 0;
  for (let i = 0; i < items.length; i += 1) {
    const item = items[i]!;
    const gross = item.unitPriceCents * item.quantity;
    const lineNet = gross - item.discountCents;
    const isLast = i === items.length - 1;
    const share = isLast
      ? totals.promoCents - assigned
      : Math.floor((totals.promoCents * lineNet) / netBase);
    assigned += share;
    result.push({
      ...item,
      promoCents: share,
      lineTotalCents: gross - item.discountCents - share,
    });
  }
  return result;
}

