import Redis, { type RedisOptions } from 'ioredis';
import type { AppConfig } from '../config.js';

export function createRedisClient(config: AppConfig, role = 'default'): Redis {
  const options: RedisOptions = {
    keyPrefix: config.redis.keyPrefix,
    connectTimeout: config.redis.connectTimeoutMs,
    commandTimeout: config.redis.commandTimeoutMs,
    maxRetriesPerRequest: config.redis.maxRetries,
    enableReadyCheck: true,
    lazyConnect: false,
    retryStrategy: (times: number) => {
      if (times > 10) return null;
      return Math.min(times * 100, 2_000);
    },
    reconnectOnError: (err: Error) => {
      if (err.message.includes('READONLY')) return 2;
      return false;
    },
    ...(config.redis.tls ? { tls: {} } : {}),
  };

  const client = new Redis(config.redis.url, options);
  client.on('error', (err: Error) => {
    if (role === 'default') {
      // eslint-disable-next-line no-console
      console.error('[redis] error:', err.message);
    }
  });
  return client;
}

import type { Cart, CartItem, CartMutation } from '../domain/cart.js';
import { emptyTotals } from '../domain/cart.js';

function asArray<T>(value: unknown): T[] {
  return Array.isArray(value) ? (value as T[]) : [];
}

/**
 * Normaliza el JSON que devuelve Lua. `cjson` codifica las tablas vacías como
 * `{}` en lugar de `[]`, por lo que hay que proteger los campos de tipo array.
 */
export function normalizeCart(raw: unknown): Cart {
  const data = raw as Partial<Cart> & Record<string, unknown>;
  const items = asArray<Record<string, unknown>>(data.items).map((item) =>
    normalizeItem(item),
  );
  const totals = (data.totals as Cart['totals'] | undefined) ?? emptyTotals(
    (data.currency as Cart['currency']) ?? 'EUR',
  );

  return {
    id: String(data.id ?? ''),
    ownerId: (data.ownerId as string | null) ?? null,
    sessionId: (data.sessionId as string | null) ?? null,
    currency: (data.currency as Cart['currency']) ?? 'EUR',
    status: (data.status as Cart['status']) ?? 'active',
    items,
    promoCodes: asArray<string>(data.promoCodes),
    totals: {
      ...emptyTotals((data.currency as Cart['currency']) ?? 'EUR'),
      ...totals,
    },
    version: Number(data.version ?? 0),
    createdAt: String(data.createdAt ?? new Date(0).toISOString()),
    updatedAt: String(data.updatedAt ?? new Date(0).toISOString()),
    expiresAt: String(data.expiresAt ?? new Date(0).toISOString()),
  };
}

function normalizeItem(item: Record<string, unknown>): CartItem {
  const breaks = asArray<{ minQuantity: number; discountBps: number }>(item.volumeBreaks);
  const metadata = (item.metadata ?? {}) as Record<string, string>;
  return {
    lineId: String(item.lineId ?? ''),
    productId: String(item.productId ?? ''),
    variantId: (item.variantId as string | null) ?? null,
    sku: String(item.sku ?? ''),
    name: String(item.name ?? ''),
    unitPriceCents: Number(item.unitPriceCents ?? 0),
    quantity: Number(item.quantity ?? 0),
    discountBps: Number(item.discountBps ?? 0),
    discountCents: Number(item.discountCents ?? 0),
    promoCents: Number(item.promoCents ?? 0),
    lineTotalCents: Number(item.lineTotalCents ?? 0),
    volumeBreaks: breaks.map((b) => ({
      minQuantity: Number(b.minQuantity),
      discountBps: Number(b.discountBps),
    })),
    metadata: typeof metadata === 'object' ? metadata : {},
  };
}

/** Serializa la mutación al payload que consume el script Lua. */
export function serializeMutation(mutation: CartMutation): { op: string; payload: unknown } {
  switch (mutation.kind) {
    case 'add_item':
      return { op: 'add_item', payload: { item: mutation.item } };
    case 'set_quantity':
      return { op: 'set_quantity', payload: { lineId: mutation.lineId, quantity: mutation.quantity } };
    case 'remove_item':
      return { op: 'remove_item', payload: { lineId: mutation.lineId } };
    case 'clear':
      return { op: 'clear', payload: {} };
    case 'apply_promo':
      return { op: 'apply_promo', payload: { code: mutation.code } };
    case 'remove_promo':
      return { op: 'remove_promo', payload: { code: mutation.code } };
    case 'checkout':
      return { op: 'checkout', payload: {} };
  }
}

import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import type Redis from 'ioredis';
import type { AppConfig } from '../config.js';
import type { Cart, CartMutation, MutationOutcome } from '../domain/cart.js';
import type { CartRepository, Clock } from '../domain/ports.js';
import { systemClock } from '../domain/ports.js';
import { normalizeCart, serializeMutation } from './cart-json.js';

const cartLua = readFileSync(fileURLToPath(new URL('./lua/cart.lua', import.meta.url)), 'utf8');
const mergeLua = readFileSync(fileURLToPath(new URL('./lua/merge.lua', import.meta.url)), 'utf8');

/**
 * Repositorio de carritos sobre Redis.
 *
 * - Toda mutación se ejecuta dentro de un script Lua (atomicidad y ausencia de
 *   lost updates entre instancias concurrentes).
 * - El versionado optimista (`expectedVersion`) permite detectar el conflicto
 *   en lugar de sobrescribir silenciosamente el trabajo de otro usuario.
 * - El estado vive fuera del proceso: las instancias de API son stateless y
 *   se pueden escalar horizontalmente sin afinidad de sesión.
 */
export class RedisCartRepository implements CartRepository {
  private readonly redis: Redis;
  private readonly config: AppConfig;
  private readonly clock: Clock;

  constructor(redis: Redis, config: AppConfig, clock: Clock = systemClock) {
    this.redis = redis;
    this.config = config;
    this.clock = clock;

    this.redis.defineCommand('cartMutate', { numberOfKeys: 1, lua: cartLua });
    this.redis.defineCommand('cartMerge', { numberOfKeys: 2, lua: mergeLua });
  }

  private get cartKey(): string {
    return 'cart:';
  }

  private ownerKey(ownerId: string): string {
    return `owner:${ownerId}`;
  }

  async create(cart: Cart): Promise<Cart> {
    await this.redis.set(
      this.cartKey + cart.id,
      JSON.stringify(cart),
      'EX',
      this.config.cart.ttlSeconds,
      'NX',
    );
    if (cart.ownerId) {
      await this.redis.zadd(
        this.ownerKey(cart.ownerId),
        this.expiresAtEpoch(cart.expiresAt),
        cart.id,
      );
    }
    return cart;
  }

  async get(cartId: string): Promise<Cart | null> {
    const raw = await this.redis.get(this.cartKey + cartId);
    if (!raw) return null;
    try {
      return normalizeCart(JSON.parse(raw));
    } catch {
      return null;
