import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import type Redis from 'ioredis';
import type { AppConfig } from '../config.js';
import type { Cart, CartMutation, MutationOutcome } from '../domain/cart.js';
import type { CartRepository, Clock, EventTemplate } from '../domain/ports.js';
import { systemClock } from '../domain/ports.js';
import { normalizeCart, serializeMutation } from './cart-json.js';

const cartLua = readFileSync(fileURLToPath(new URL('./lua/cart.lua', import.meta.url)), 'utf8');
const mergeLua = readFileSync(fileURLToPath(new URL('./lua/merge.lua', import.meta.url)), 'utf8');

/**
 * Repositorio de carritos sobre Redis.
 *
 * - Toda mutación se ejecuta dentro de un script Lua (atomicidad y ausencia de
 *   lost updates entre instancias concurrentes).
 * - El versionado optimista (`expectedVersion`) permite detectar el conflicto
 *   en lugar de sobrescribir silenciosamente el trabajo de otro usuario.
 * - El estado vive fuera del proceso: las instancias de API son stateless y
 *   se pueden escalar horizontalmente sin afinidad de sesión.
 * - La mutación y el evento de dominio se escriben en el mismo script
 *   (patrón outbox transaccional): nunca hay estado sin evento ni evento sin
 *   estado.
 */
export class RedisCartRepository implements CartRepository {
  private readonly redis: Redis;
  private readonly config: AppConfig;
  private readonly clock: Clock;

  constructor(redis: Redis, config: AppConfig, clock: Clock = systemClock) {
    this.redis = redis;
    this.config = config;
    this.clock = clock;

    this.redis.defineCommand('cartMutate', { numberOfKeys: 2, lua: cartLua });
    this.redis.defineCommand('cartMerge', { numberOfKeys: 3, lua: mergeLua });
  }

  private cartKey(cartId: string): string {
    return `cart:${cartId}`;
  }

  private ownerKey(ownerId: string): string {
    return `owner:${ownerId}`;
  }

  private get streamKey(): string {
    return 'events:cart';
  }

  async create(cart: Cart, event?: EventTemplate): Promise<Cart> {
    const now = this.clock.now();
    const result = (await this.redis.cartMutate(
      this.cartKey(cart.id),
      this.streamKey,
      'create',
      JSON.stringify(cart),
      -1,
      JSON.stringify(this.config.pricing),
      now.toISOString(),
      this.expiresAt(now).toISOString(),
      this.config.cart.ttlSeconds,
      this.eventJson(event),
      this.config.events.streamMaxLen,
    )) as [string, string, string];

    if (result[0] !== 'ok') {
      throw new Error(`No se pudo crear el carrito ${cart.id}: ${result[2] || result[0]}`);
    }

    if (cart.ownerId) {
      await this.redis.zadd(
        this.ownerKey(cart.ownerId),
        this.expiresAtEpoch(this.expiresAt(now).toISOString()),
        cart.id,
      );
    }

    return normalizeCart(JSON.parse(result[2]));
  }

  async get(cartId: string): Promise<Cart | null> {
    const raw = await this.redis.get(this.cartKey(cartId));
    if (!raw) return null;
    try {
      return normalizeCart(JSON.parse(raw));
    } catch {
      return null;
    }
  }

  async mutate(
    cartId: string,
    expectedVersion: number | null,
    mutation: CartMutation,
    event?: EventTemplate,
  ): Promise<MutationOutcome> {
    const { op, payload } = serializeMutation(mutation);
    const now = this.clock.now();
    const result = (await this.redis.cartMutate(
      this.cartKey(cartId),
      this.streamKey,
      op,
      JSON.stringify(payload),
      expectedVersion === null ? -1 : expectedVersion,
      JSON.stringify(this.config.pricing),
      now.toISOString(),
      this.expiresAt(now).toISOString(),
      this.config.cart.ttlSeconds,
      this.eventJson(event),
      this.config.events.streamMaxLen,
    )) as [string, string, string];

    return this.toOutcome(result);
  }

  async merge(
    targetCartId: string,
    sourceCartId: string,
    expectedVersion: number | null,
    event?: EventTemplate,
  ): Promise<MutationOutcome> {
    const now = this.clock.now();
    const result = (await this.redis.cartMerge(
      this.cartKey(targetCartId),
      this.cartKey(sourceCartId),
      this.streamKey,
      expectedVersion === null ? -1 : expectedVersion,
      JSON.stringify(this.config.pricing),
      now.toISOString(),
      this.expiresAt(now).toISOString(),
      this.config.cart.ttlSeconds,
      this.eventJson(event),
      this.config.events.streamMaxLen,
    )) as [string, string, string];

    if (result[0] === 'source_not_found') {
      return { status: 'not_found' };
    }
    return this.toOutcome(result);
  }

  async remove(cartId: string): Promise<void> {
    const cart = await this.get(cartId);
    await this.redis.del(this.cartKey(cartId));
    if (cart?.ownerId) {
      await this.redis.zrem(this.ownerKey(cart.ownerId), cartId);
    }
  }

  async findActiveByOwner(ownerId: string): Promise<Cart[]> {
    const key = this.ownerKey(ownerId);
    const nowEpoch = Math.floor(this.clock.now().getTime() / 1000);
    const ids = await this.redis.zrangebyscore(key, nowEpoch, '+inf');
    if (ids.length === 0) return [];
    const raws = await this.redis.mget(ids.map((id) => this.cartKey(id)));
    const carts: Cart[] = [];
    for (const raw of raws) {
      if (!raw) continue;
      try {
        carts.push(normalizeCart(JSON.parse(raw)));
      } catch {
        // registro corrupto: se ignora
      }
    }
    await this.redis.zremrangebyscore(key, '-inf', nowEpoch);
    return carts;
  }

  private eventJson(event?: EventTemplate): string {
    if (!event) return '';
    return JSON.stringify({
      id: event.id,
      type: event.type,
      occurredAt: event.occurredAt,
      actorId: event.actorId,
      payload: event.payload,
    });
  }

  private toOutcome(result: [string, string, string]): MutationOutcome {
    const [status, version, payload] = result;
    switch (status) {
      case 'ok':
        return { status: 'ok', cart: normalizeCart(JSON.parse(payload)) };
      case 'not_found':
        return { status: 'not_found' };
      case 'conflict':
        return { status: 'conflict', current: normalizeCart(JSON.parse(payload)) };
      case 'invalid':
        return { status: 'invalid', code: payload, message: `Invalid cart operation: ${payload}` };
      default:
        throw new Error(`Resultado inesperado del script de carrito: ${status} (${version})`);
    }
  }

  private expiresAt(now: Date): Date {
    return new Date(now.getTime() + this.config.cart.ttlSeconds * 1000);
  }

  private expiresAtEpoch(iso: string): number {
    const parsed = Date.parse(iso);
    return Number.isFinite(parsed) ? Math.floor(parsed / 1000) : 0;
  }
}

import type { AppConfig } from '../config.js';
import type { Cart, CartItem, CartMutation, MutationOutcome } from '../domain/cart.js';
import { computeTotals, proratePromo } from '../domain/pricing.js';
import type { CartRepository, Clock, EventTemplate } from '../domain/ports.js';
import { systemClock } from '../domain/ports.js';
import { resolveVolumeBreak } from '../domain/catalog.js';

/**
 * Repositorio en memoria. Se usa como degradación elegante cuando Redis no
 * está disponible y en las pruebas unitarias. Mantiene la misma semántica que
 * el script Lua (incluido el versionado optimista) serializando las
 * operaciones por carrito mediante una cola de promesas.
 */
export class MemoryCartRepository implements CartRepository {
  private readonly carts = new Map<string, Cart>();
  private readonly locks = new Map<string, Promise<unknown>>();
  private readonly config: AppConfig;
  private readonly clock: Clock;

  constructor(config: AppConfig, clock: Clock = systemClock) {
    this.config = config;
    this.clock = clock;
  }

  async create(cart: Cart, _event?: EventTemplate): Promise<Cart> {
    const now = this.clock.now();
    const created: Cart = {
      ...cart,
      version: 1,
      createdAt: now.toISOString(),
      updatedAt: now.toISOString(),
      expiresAt: this.expiresAt(now).toISOString(),
    };
    this.reprice(created);
    this.carts.set(created.id, created);
    return structuredClone(created);
  }

  async get(cartId: string): Promise<Cart | null> {
    const cart = this.carts.get(cartId);
    return cart ? structuredClone(cart) : null;
  }

  async mutate(
    cartId: string,
    expectedVersion: number | null,
    mutation: CartMutation,
    _event?: EventTemplate,
  ): Promise<MutationOutcome> {
    return this.withLock(cartId, async () => {
      const cart = this.carts.get(cartId);
      if (!cart) return { status: 'not_found' };
      if (cart.status !== 'active') {
        return { status: 'invalid', code: 'CART_ALREADY_CHECKED_OUT', message: 'Carrito no activo' };
      }
      if (expectedVersion !== null && cart.version !== expectedVersion) {
        return { status: 'conflict', current: structuredClone(cart) };
      }

      const maxQty = this.config.cart.maxQuantityPerLine;
      const maxItems = this.config.cart.maxItems;

      switch (mutation.kind) {
        case 'add_item': {
          const item = mutation.item;
          if (item.quantity <= 0 || item.quantity > maxQty) {
            return { status: 'invalid', code: 'INVALID_QUANTITY', message: 'Cantidad inválida' };
          }
          const existing = cart.items.find((i) => i.lineId === item.lineId);
          if (existing) {
            const newQty = existing.quantity + item.quantity;
            if (newQty > maxQty) {
              return { status: 'invalid', code: 'INVALID_QUANTITY', message: 'Cantidad inválida' };
            }
            existing.quantity = newQty;
            existing.discountBps = resolveVolumeBreak(existing.volumeBreaks, newQty);
          } else {
            if (cart.items.length >= maxItems) {
              return {
                status: 'invalid',
                code: 'CART_LIMIT_EXCEEDED',
                message: 'Demasiadas líneas',
              };
            }
            cart.items.push({
              ...item,
              discountBps: resolveVolumeBreak(item.volumeBreaks, item.quantity),
              discountCents: 0,
              promoCents: 0,
              lineTotalCents: 0,
            });
          }
          break;
        }
        case 'set_quantity': {
          if (mutation.quantity < 0 || mutation.quantity > maxQty) {
            return { status: 'invalid', code: 'INVALID_QUANTITY', message: 'Cantidad inválida' };
          }
          const index = cart.items.findIndex((i) => i.lineId === mutation.lineId);
          if (index === -1) {
            return {
              status: 'invalid',
              code: 'CART_LINE_NOT_FOUND',
              message: 'Línea no encontrada',
            };
          }
          if (mutation.quantity === 0) {
            cart.items.splice(index, 1);
          } else {
            const item = cart.items[index]!;
            item.quantity = mutation.quantity;
            item.discountBps = resolveVolumeBreak(item.volumeBreaks, mutation.quantity);
          }
          break;
        }
        case 'remove_item': {
          const index = cart.items.findIndex((i) => i.lineId === mutation.lineId);
          if (index === -1) {
            return {
              status: 'invalid',
              code: 'CART_LINE_NOT_FOUND',
              message: 'Línea no encontrada',
            };
          }
          cart.items.splice(index, 1);
          break;
        }
        case 'clear':
          cart.items = [];
          cart.promoCodes = [];
          break;
        case 'apply_promo': {
          if (!this.config.pricing.promos[mutation.code]) {
            return {
              status: 'invalid',
              code: 'PROMO_NOT_FOUND',
              message: 'Cupón no encontrado',
            };
          }
          if (!cart.promoCodes.includes(mutation.code)) {
            cart.promoCodes.push(mutation.code);
          }
          break;
        }
        case 'remove_promo':
          cart.promoCodes = cart.promoCodes.filter((c) => c !== mutation.code);
          break;
        case 'checkout':
          cart.status = 'checked_out';
          break;
      }

      this.reprice(cart);
      cart.version += 1;
      cart.updatedAt = this.clock.now().toISOString();
      cart.expiresAt = this.expiresAt(this.clock.now()).toISOString();
      return { status: 'ok', cart: structuredClone(cart) };
    });
  }

  async merge(
    targetCartId: string,
    sourceCartId: string,
    expectedVersion: number | null,
    _event?: EventTemplate,
  ): Promise<MutationOutcome> {
    return this.withLock(targetCartId, async () => {
      const target = this.carts.get(targetCartId);
      if (!target) return { status: 'not_found' };
      if (target.status !== 'active') {
        return { status: 'invalid', code: 'CART_ALREADY_CHECKED_OUT', message: 'Carrito no activo' };
      }
      if (expectedVersion !== null && target.version !== expectedVersion) {
        return { status: 'conflict', current: structuredClone(target) };
      }
      const source = this.carts.get(sourceCartId);
      if (!source) return { status: 'not_found' };

      const maxQty = this.config.cart.maxQuantityPerLine;
      for (const srcItem of source.items) {
        const existing = target.items.find((i) => i.lineId === srcItem.lineId);
        if (existing) {
          existing.quantity = Math.min(maxQty, existing.quantity + srcItem.quantity);
          existing.discountBps = resolveVolumeBreak(existing.volumeBreaks, existing.quantity);
        } else if (target.items.length < this.config.cart.maxItems) {
          target.items.push({
            ...srcItem,
            discountBps: resolveVolumeBreak(srcItem.volumeBreaks, srcItem.quantity),
            discountCents: 0,
            promoCents: 0,
            lineTotalCents: 0,
          });
        }
      }
      for (const code of source.promoCodes) {
        if (!target.promoCodes.includes(code)) target.promoCodes.push(code);
      }

      this.reprice(target);
      target.version += 1;
      target.updatedAt = this.clock.now().toISOString();
      target.expiresAt = this.expiresAt(this.clock.now()).toISOString();
      this.carts.delete(sourceCartId);
      return { status: 'ok', cart: structuredClone(target) };
    });
  }

  async remove(cartId: string): Promise<void> {
    this.carts.delete(cartId);
  }

  async findActiveByOwner(ownerId: string): Promise<Cart[]> {
    const now = this.clock.now().getTime();
    return [...this.carts.values()]
      .filter((c) => c.ownerId === ownerId && c.status === 'active' && Date.parse(c.expiresAt) > now)
      .map((c) => structuredClone(c));
  }

  private reprice(cart: Cart): void {
    const totals = computeTotals({
      items: cart.items,
      promoCodes: cart.promoCodes,
      currency: cart.currency,
      shippingFlatCents: this.config.pricing.shippingFlatCents,
      freeShippingThresholdCents: this.config.pricing.freeShippingThresholdCents,
      taxBps: this.config.pricing.taxBps,
      promos: this.config.pricing.promos,
    });
    cart.totals = totals;
    cart.items = proratePromo(cart.items as CartItem[], totals);
  }

  private expiresAt(now: Date): Date {
    return new Date(now.getTime() + this.config.cart.ttlSeconds * 1000);
  }

  private async withLock<T>(id: string, fn: () => Promise<T>): Promise<T> {
    const previous = this.locks.get(id) ?? Promise.resolve();
    const result = previous.then(fn, fn);
    this.locks.set(
      id,
      result.catch(() => undefined),
    );
    try {
      return await result;
    } finally {
      if (this.locks.get(id) === result) this.locks.delete(id);
    }
  }
}

/**
 * Caché local (LRU + TTL) para lecturas de carrito.
 *
 * Reduce la presión sobre Redis en los hottest paths (el `GET` de un carrito es
 * la operación más frecuente de un e-commerce). La invalidación se hace por
 * escritura: cualquier mutación en esta instancia borra su entrada local y,
 * como el TTL es corto, las demás instancias convergen en milisegundos.
 */
export class LruCache<T> {
  private readonly entries = new Map<string, { value: T; expiresAt: number }>();
  private readonly maxEntries: number;
  private readonly ttlMs: number;

  constructor(maxEntries: number, ttlMs: number) {
    this.maxEntries = Math.max(1, maxEntries);
    this.ttlMs = ttlMs;
  }

  get(key: string): T | undefined {
    const entry = this.entries.get(key);
    if (!entry) return undefined;
    if (entry.expiresAt <= Date.now()) {
      this.entries.delete(key);
      return undefined;
    }
    // refresca la recencia (LRU)
    this.entries.delete(key);
    this.entries.set(key, entry);
    return entry.value;
  }

  set(key: string, value: T): void {
    if (this.ttlMs <= 0) return;
    if (this.entries.has(key)) this.entries.delete(key);
    this.entries.set(key, { value, expiresAt: Date.now() + this.ttlMs });
    while (this.entries.size > this.maxEntries) {
      const oldest = this.entries.keys().next();
      if (oldest.done) break;
      this.entries.delete(oldest.value);
    }
  }

  delete(key: string): void {
    this.entries.delete(key);
  }

  clear(): void {
    this.entries.clear();
  }

  get size(): number {
    return this.entries.size;
  }
}

import { randomUUID } from 'node:crypto';
import type Redis from 'ioredis';
import type { IdempotencyStore, StoredResponse } from '../domain/ports.js';

const RELEASE_SCRIPT = `
if redis.call('GET', KEYS[1]) == ARGV[1] then
  return redis.call('DEL', KEYS[1])
end
return 0
`;

/**
 * Almacén de idempotencia respaldado por Redis.
 *
 * Permite que un cliente reintente una mutación (tiempo de red inestable,
 * reintentos de SDK, doble clic) sin duplicar efectos. La clave se guarda
 * junto con la respuesta completa y se reproduce tal cual.
 */
export class RedisIdempotencyStore implements IdempotencyStore {
  private readonly redis: Redis;

  constructor(redis: Redis) {
    this.redis = redis;
    this.redis.defineCommand('releaseLock', { numberOfKeys: 1, lua: RELEASE_SCRIPT });
  }

  private resultKey(key: string): string {
    return `idem:${key}`;
  }

  private lockKey(key: string): string {
    return `idemlock:${key}`;
  }

  async get(key: string): Promise<StoredResponse | null> {
    const raw = await this.redis.get(this.resultKey(key));
    if (!raw) return null;
    try {
      return JSON.parse(raw) as StoredResponse;
    } catch {
      return null;
    }
  }

  async lock(key: string, token: string, ttlSeconds: number): Promise<boolean> {
    const res = await this.redis.set(this.lockKey(key), token, 'PX', ttlSeconds * 1000, 'NX');
    return res === 'OK';
  }

  async release(key: string, token: string): Promise<void> {
    await this.redis.releaseLock(this.lockKey(key), token);
  }

  async save(key: string, response: StoredResponse, ttlSeconds: number): Promise<void> {
    await this.redis.set(
      this.resultKey(key),
      JSON.stringify(response),
      'EX',
      ttlSeconds,
    );
  }

  async waitForResult(key: string, timeoutMs: number): Promise<StoredResponse | null> {
    const deadline = Date.now() + timeoutMs;
    while (Date.now() < deadline) {
      const stored = await this.get(key);
      if (stored) return stored;
      await new Promise((resolve) => setTimeout(resolve, 25));
    }
    return null;
  }
}

export function newIdempotencyToken(): string {
  return randomUUID();
}

import type Redis from 'ioredis';
import type { RateLimiter, RateLimitResult } from '../domain/ports.js';

/**
 * Token bucket distribuido. Todo el estado vive en Redis, de modo que el
 * límite se respeta entre todas las réplicas de la API (un límite en memoria
 * del proceso sería multiplicado por el número de instancias).
 *
 * Se calculan los tokens en mili-tokens (enteros) porque Redis convierte los
 * números de Lua a enteros al pasarlos como argumentos.
 */
const TOKEN_BUCKET_SCRIPT = `
local key = KEYS[1]
local capacity = tonumber(ARGV[1])
local refillPerSecond = tonumber(ARGV[2])
local cost = tonumber(ARGV[3])
local nowMs = tonumber(ARGV[4])
local ttlMs = tonumber(ARGV[5])

local capacityMilli = capacity * 1000
local costMilli = cost * 1000

local data = redis.call('HMGET', key, 'tokens', 'ts')
local tokens = tonumber(data[1])
local ts = tonumber(data[2])
if tokens == nil then
  tokens = capacityMilli
  ts = nowMs
end

local elapsed = nowMs - ts
if elapsed < 0 then elapsed = 0 end
tokens = tokens + (elapsed * refillPerSecond)
if tokens > capacityMilli then tokens = capacityMilli end

local allowed = 0
if tokens >= costMilli then
  tokens = tokens - costMilli
  allowed = 1
end

local retryAfterMs = 0
if allowed == 0 then
  retryAfterMs = math.ceil((costMilli - tokens) / refillPerSecond)
end

redis.call('HSET', key, 'tokens', tokens, 'ts', nowMs)
redis.call('PEXPIRE', key, ttlMs)

return { allowed, tostring(tokens), tostring(retryAfterMs), tostring(capacity) }
`;

export class RedisRateLimiter implements RateLimiter {
  private readonly redis: Redis;
  private readonly capacity: number;
  private readonly refillPerSecond: number;

  constructor(redis: Redis, capacity: number, refillPerSecond: number) {
    this.redis = redis;
    this.capacity = capacity;
    this.refillPerSecond = refillPerSecond;
    this.redis.defineCommand('tokenBucket', { numberOfKeys: 1, lua: TOKEN_BUCKET_SCRIPT });
  }

  async consume(key: string, cost = 1): Promise<RateLimitResult> {
    const nowMs = Date.now();
    const ttlMs = Math.max(1_000, Math.ceil((this.capacity / this.refillPerSecond) * 2_000));
    const result = (await this.redis.tokenBucket(
      `ratelimit:${key}`,
      this.capacity,
      this.refillPerSecond,
      cost,
      nowMs,
      ttlMs,
    )) as [number, string, string, string];

    const allowed = Number(result[0]) === 1;
    const tokensMilli = Number(result[1]);
    const retryAfterMs = Number(result[2]);
    return {
      allowed,
      limit: Number(result[3]),
      remaining: Math.max(0, Math.floor(tokensMilli / 1000)),
      retryAfterSeconds: allowed ? 0 : Math.max(1, Math.ceil(retryAfterMs / 1000)),
    };
  }
}

/** Limitador en proceso: degradación elegante si Redis no responde. */
export class MemoryRateLimiter implements RateLimiter {
  private readonly buckets = new Map<string, { tokens: number; updatedAt: number }>();
  private readonly capacity: number;
  private readonly refillPerSecond: number;

  constructor(capacity: number, refillPerSecond: number) {
    this.capacity = capacity;
    this.refillPerSecond = refillPerSecond;
  }

  async consume(key: string, cost = 1): Promise<RateLimitResult> {
    const now = Date.now();
    const bucket = this.buckets.get(key) ?? { tokens: this.capacity, updatedAt: now };
    const elapsedSeconds = Math.max(0, now - bucket.updatedAt) / 1000;
    bucket.tokens = Math.min(this.capacity, bucket.tokens + elapsedSeconds * this.refillPerSecond);
    bucket.updatedAt = now;

    let allowed = true;
    if (bucket.tokens < cost) {
      allowed = false;
    } else {
      bucket.tokens -= cost;
    }
    this.buckets.set(key, bucket);

    return {
      allowed,
      limit: this.capacity,
      remaining: Math.floor(bucket.tokens),
      retryAfterSeconds: allowed
        ? 0
        : Math.max(1, Math.ceil((cost - bucket.tokens) / this.refillPerSecond)),
    };
  }
}

import { randomUUID } from 'node:crypto';
import type Redis from 'ioredis';
import type { DomainEvent, EventPublisher } from '../domain/ports.js';

/**
 * Publicador de eventos sobre Redis Streams.
 *
 * Los eventos ligados a una mutación de carrito se escriben dentro del propio
 * script Lua (outbox transaccional). Este publicador se usa para eventos que
 * no accompanyState mutaciones (p. ej. `cart.viewed` o señales operativas) y
 * para consumers que leen del stream con grupos de consumidores.
 */
export class RedisEventPublisher implements EventPublisher {
  private readonly redis: Redis;
  private readonly streamKey: string;
  private readonly maxLen: number;

  constructor(redis: Redis, streamKey = 'events:cart', maxLen = 100_000) {
    this.redis = redis;
    this.streamKey = streamKey;
    this.maxLen = maxLen;
  }

  async publish(event: DomainEvent): Promise<void> {
    await this.redis.xadd(
      this.streamKey,
      'MAXLEN',
      '~',
      this.maxLen,
      '*',
      'type',
      event.type,
      'id',
      event.id,
      'cartId',
      event.cartId,
      'version',
      String(event.version),
      'occurredAt',
      event.occurredAt,
      'actorId',
      event.actorId ?? '',
      'data',
      JSON.stringify(event.payload),
    );
  }
}

export function newEventId(): string {
  return randomUUID();
}

