  async getCart(cartId, actor): Promise<Cart>
  async addItem(cartId, actor, input, expectedVersion): Promise<Cart>
  async setQuantity(cartId, actor, lineId, quantity, expectedVersion)
  async removeItem(...)
  async clear(...)
  async applyPromo(cartId, actor, code, expectedVersion)
