Actor authorization:
```ts
private assertAccess(cart: Cart, actor: Actor): void {
  if (cart.ownerId) {
    if (!actor.userId) throw new UnauthorizedError();
    if (cart.ownerId !== actor.userId) throw new ForbiddenError();
    return;
  }
  // guest cart
  if (actor.userId) {
    // a logged-in user may access a guest cart only if it belongs to their session
    if (cart.sessionId && actor.sessionId && cart.sessionId !== actor.sessionId) throw new ForbiddenError();
    return;
  }
  if (cart.sessionId && actor.sessionId && cart.sessionId !== actor.sessionId) throw new ForbiddenError();
}
