import { randomUUID } from 'node:crypto';
import type { IdempotencyStore } from '../domain/ports.js';

export interface IdempotentResult<T> {
  statusCode: number;
  body: T;
  replayed: boolean;
}

/**
 * Ejecuta una mutación de forma idempotente.
 *
 * Con la cabecera `Idempotency-Key` el cliente puede reintentar sin miedo a
 * duplicar efectos: la primera ejecución guarda su respuesta y las
 * siguientes la reproducen tal cual. La respuesta incluye `Idempotent-Replay`
 * para que el cliente sepa que se trata de una repetición.
 */
export async function withIdempotency<T>(
  store: IdempotencyStore,
  scope: string,
  key: string | undefined,
  ttlSeconds: number,
  operation: () => Promise<{ statusCode: number; body: T }>,
): Promise<IdempotentResult<T>> {
  if (!key) {
    const result = await operation();
    return { ...result, replayed: false };
  }

  const scopedKey = `${scope}:${key}`;
  const existing = await store.get(scopedKey);
  if (existing) {
    return { statusCode: existing.statusCode, body: existing.body as T, replayed: true };
  }

  const token = randomUUID();
  const acquired = await store.lock(scopedKey, token, 30);
  if (!acquired) {
    const pending = await store.waitForResult(scopedKey, 5_000);
    if (pending) {
      return { statusCode: pending.statusCode, body: pending.body as T, replayed: true };
    }
  }

  try {
    const result = await operation();
    await store.save(scopedKey, result, ttlSeconds);
    return { ...result, replayed: false };
  } finally {
    if (acquired) await store.release(scopedKey, token);
  }
}

import { randomUUID } from 'node:crypto';
import type { FastifyInstance, FastifyReply, FastifyRequest } from 'fastify';
import type { AppConfig } from '../../config.js';
import type { Actor } from '../../application/cart-service.js';
import { UnauthorizedError } from '../../domain/errors.js';
import { parseCookies, verifyToken } from '../auth.js';

declare module 'fastify' {
  interface FastifyRequest {
    actor: Actor;
    sessionId: string | null;
  }
}

/**
 * Resuelve la identidad de la petición: usuario autenticado (JWT Bearer) y/o
 * sesión de invitado (cookie `sid` o cabecera `x-session-id`).
 *
 * El proceso no guarda estado de sesión: la identidad viaja en el token o en
 * la cookie, de modo que cualquier réplica del servicio puede atenderla.
 */
export function registerContext(app: FastifyInstance, config: AppConfig): void {
  app.decorateRequest('actor', null as unknown as Actor);
  app.decorateRequest('sessionId', null as unknown as string | null);

  app.addHook('onRequest', async (request: FastifyRequest, reply: FastifyReply) => {
    const cookies = parseCookies(request.headers.cookie);
    const headerSession = request.headers['x-session-id'];
    let sessionId: string | null =
      typeof headerSession === 'string' && headerSession ? headerSession : (cookies.sid ?? null);

    let userId: string | null = null;
    const auth = request.headers.authorization;
    if (auth) {
      if (!auth.startsWith('Bearer ')) {
        throw new UnauthorizedError('Formato de cabecera Authorization inválido');
      }
      const payload = verifyToken(
        auth.slice('Bearer '.length),
        config.auth.secret,
        config.auth.issuer,
      );
      if (!payload) throw new UnauthorizedError();
      userId = payload.sub;
    }

    if (!sessionId && !userId) {
      sessionId = randomUUID();
      reply.header(
        'set-cookie',
        `sid=${sessionId}; Path=/; HttpOnly; SameSite=Lax; Max-Age=${60 * 60 * 24 * 14}`,
      );
    }

    request.actor = { userId, sessionId };
    request.sessionId = sessionId;
  });
}

import type { FastifyInstance, FastifyReply, FastifyRequest } from 'fastify';
import type { RateLimiter } from '../../domain/ports.js';
import { RateLimitedError } from '../../domain/errors.js';

const PUBLIC_PATHS = new Set(['/healthz', '/readyz', '/metrics']);

/**
 * Rate limiting distribuido (token bucket en Redis). La clave es el usuario
 * autenticado o, si no, la sesión de invitado; por último se recurre a la IP.
 * Al vivir el estado en Redis el límite es global para el servicio, no por
 * réplica.
 */
export function registerRateLimit(
  app: FastifyInstance,
  limiter: RateLimiter,
  options: { enabled: boolean },
): void {
  if (!options.enabled) return;

  app.addHook('onRequest', async (request: FastifyRequest, reply: FastifyReply) => {
    const path = request.url.split('?')[0] ?? request.url;
    if (PUBLIC_PATHS.has(path)) return;

    const actor = request.actor;
    const key = actor?.userId ?? actor?.sessionId ?? request.ip;

    const result = await limiter.consume(key);
    reply.header('x-ratelimit-limit', String(result.limit));
    reply.header('x-ratelimit-remaining', String(result.remaining));
    if (!result.allowed) {
      throw new RateLimitedError(result.retryAfterSeconds);
    }
  });
}

