function expectedVersion(request): number | null {
  const ifMatch = request.headers['if-match'];
  const raw = typeof ifMatch === 'string' ? ifMatch : request.headers['x-cart-version'];
  if (raw === undefined) return null;
  const cleaned = raw.replace(/"/g, '').trim();
