import type { Cart, CartMutation, MutationOutcome } from '../domain/cart.js';
import type { CartRepository, EventTemplate } from '../domain/ports.js';

/**
 * Repositorio resiliente: si Redis no responde, degrada a un repositorio en
 * memoria para no tumbar el servicio. La degradación se registra para que
 * sea visible en monitorización.
 *
 * Nota: los scripts Lua son atómicos, por lo que un error de red implica que
 * la mutación no se aplicó (o se aplicó sin confirmar la respuesta, caso en
 * el que la versión esperada protege contra la doble aplicación).
 */
export class ResilientCartRepository implements CartRepository {
  private degraded = false;

  constructor(
    private readonly primary: CartRepository,
    private readonly fallback: CartRepository,
    private readonly logger?: { warn: (obj: unknown, msg?: string) => void },
  ) {}

  get isDegraded(): boolean {
    return this.degraded;
  }

  async create(cart: Cart, event?: EventTemplate): Promise<Cart> {
    return this.run(() => this.primary.create(cart, event), () => this.fallback.create(cart, event));
  }

  async get(cartId: string): Promise<Cart | null> {
    return this.run(
      () => this.primary.get(cartId),
      () => this.fallback.get(cartId),
    );
  }

  async mutate(
    cartId: string,
    expectedVersion: number | null,
    mutation: CartMutation,
    event?: EventTemplate,
  ): Promise<MutationOutcome> {
    return this.run(
      () => this.primary.mutate(cartId, expectedVersion, mutation, event),
      () => this.fallback.mutate(cartId, expectedVersion, mutation, event),
    );
  }

  async merge(
    targetCartId: string,
    sourceCartId: string,
    expectedVersion: number | null,
    event?: EventTemplate,
  ): Promise<MutationOutcome> {
    return this.run(
      () => this.primary.merge(targetCartId, sourceCartId, expectedVersion, event),
      () => this.fallback.merge(targetCartId, sourceCartId, expectedVersion, event),
    );
  }

  async remove(cartId: string): Promise<void> {
    return this.run(
      () => this.primary.remove(cartId),
      () => this.fallback.remove(cartId),
    );
  }

  async findActiveByOwner(ownerId: string): Promise<Cart[]> {
    return this.run(
      () => this.primary.findActiveByOwner(ownerId),
      () => this.fallback.findActiveByOwner(ownerId),
    );
  }

  private async run<T>(primary: () => Promise<T>, fallback: () => Promise<T>): Promise<T> {
    try {
      const result = await primary();
      if (this.degraded) {
        this.degraded = false;
        this.logger?.warn({}, 'Redis recuperado: se vuelve al repositorio principal');
      }
      return result;
    } catch (err) {
      if (!this.degraded) {
        this.degraded = true;
        this.logger?.warn({ err }, 'Redis no disponible: modo degradado en memoria');
      }
      return fallback();
    }
  }
}

import pino, { type Logger } from 'pino';
import type { FastifyInstance } from 'fastify';
import type { AppConfig } from './config.js';
import { CartService } from './application/cart-service.js';
import type { Cart } from './domain/cart.js';
import { buildApp, createMetrics } from './http/app.js';
import { HttpCatalog, MemoryCatalog } from './infrastructure/catalog.js';
import { LruCache } from './infrastructure/lru-cache.js';
import { MemoryCartRepository } from './infrastructure/memory-cart-repository.js';
import { RedisCartRepository } from './infrastructure/redis-cart-repository.js';
import { RedisEventPublisher } from './infrastructure/redis-event-publisher.js';
import { RedisIdempotencyStore } from './infrastructure/redis-idempotency-store.js';
import { MemoryRateLimiter, RedisRateLimiter } from './infrastructure/rate-limit.js';
import { ResilientCartRepository } from './infrastructure/resilient-repository.js';
import { createRedisClient } from './infrastructure/redis.js';

export interface Runtime {
  app: FastifyInstance;
  logger: Logger;
  close: () => Promise<void>;
  redisHealthy: () => boolean;
}

export function createLogger(config: AppConfig): Logger {
  return pino({
    level: config.logLevel,
    base: { service: 'carrito-api' },
    ...(config.logPretty ? { transport: { target: 'pino-pretty' } } : {}),
  });
}

/**
 * Cableado de la aplicación: Redis como fuente de verdad, caché local para
 * lecturas, rate limiting distribuido, idempotencia y outbox transaccional.
 */
export async function createRuntime(config: AppConfig): Promise<Runtime> {
  const logger = createLogger(config);
  const redis = createRedisClient(config);

  const metrics = createMetrics();

  const redisRepository = new RedisCartRepository(redis, config);
  const memoryRepository = new MemoryCartRepository(config);
  const repository = new ResilientCartRepository(redisRepository, memoryRepository, logger);

  const catalog =
    config.catalog.mode === 'http' && config.catalog.url
      ? new HttpCatalog(config.catalog.url, config.catalog.timeoutMs)
      : new MemoryCatalog();

  const publisher = new RedisEventPublisher(redis, 'events:cart', config.events.streamMaxLen);
  const idempotency = new RedisIdempotencyStore(redis);
  const rateLimiter = config.rateLimit.enabled
    ? new RedisRateLimiter(redis, config.rateLimit.capacity, config.rateLimit.refillPerSecond)
    : new MemoryRateLimiter(config.rateLimit.capacity, config.rateLimit.refillPerSecond);

  const cache = new LruCache<Cart>(config.cache.maxEntries, config.cache.ttlMs);

  const service = new CartService({
    repository,
    catalog,
    publisher,
    config,
    cache,
    logger,
  });

  const app = await buildApp({
    config,
    service,
    idempotency,
    rateLimiter,
    metrics,
    readiness: async () => redis.status === 'ready' || redis.status === 'connecting',
  });

  app.log.info(
    {
      env: config.env,
      port: config.port,
      redis: config.redis.url,
      catalog: config.catalog.mode,
    },
    'API de carrito iniciada',
  );

  return {
    app,
    logger,
    redisHealthy: () => redis.status === 'ready',
    close: async () => {
      await app.close();
      redis.disconnect();
    },
  };
}

import { loadConfig } from './config.js';
import { createRuntime } from './bootstrap.js';

const config = loadConfig();
const runtime = await createRuntime(config);

await runtime.app.listen({ port: config.port, host: config.host });

let shuttingDown = false;
const shutdown = async (signal: string): Promise<void> => {
  if (shuttingDown) return;
  shuttingDown = true;
  runtime.logger.info({ signal }, 'apagando el servicio');
  try {
    await runtime.close();
  } catch (err) {
    runtime.logger.error({ err }, 'error durante el apagado');
  }
  process.exit(0);
};

process.on('SIGTERM', () => void shutdown('SIGTERM'));
process.on('SIGINT', () => void shutdown('SIGINT'));
process.on('unhandledRejection', (err) => {
  runtime.logger.error({ err }, 'promesa no gestionada');
});

