import { loadConfig } from './config.js';
import { createLogger } from './bootstrap.js';
import { createRedisClient } from './infrastructure/redis.js';

/**
 * Consumidor de eventos del carrito.
 *
 * Lee el stream de Redis con un grupo de consumidores: varios workers pueden
 * procesar en paralelo repartiendo los mensajes, y si uno cae, sus mensajes
 * pendientes se recuperan con XAUTOCLAIM. Esto permite escalar el
 * procesamiento de forma independiente de la API.
 */
const config = loadConfig();
const logger = createLogger(config);
const redis = createRedisClient(config, 'worker');

const STREAM = 'events:cart';
const GROUP = config.worker.consumerGroup;
const CONSUMER = `${config.worker.consumerName}-${process.pid}`;

let running = true;

async function ensureGroup(): Promise<void> {
  try {
    await redis.xgroup('CREATE', STREAM, GROUP, '0', 'MKSTREAM');
    logger.info({ group: GROUP, consumer: CONSUMER }, 'grupo de consumidores creado');
  } catch (err) {
    if (!(err instanceof Error) || !err.message.includes('BUSYGROUP')) throw err;
  }
}

async function reclaimPending(): Promise<void> {
  const result = (await redis.xautoclaim(
    STREAM,
    GROUP,
    CONSUMER,
    30_000,
    '0-0',
    'COUNT',
    config.worker.batchSize,
  )) as [string, string[][], string[]?];

  const entries = result?.[1] ?? [];
  for (const entry of entries) {
    await handle(entry[0] as string, entry[1] as string[]);
  }
}

async function handle(id: string, fields: string[]): Promise<void> {
  const map: Record<string, string> = {};
  for (let i = 0; i < fields.length; i += 2) {
    map[fields[i] as string] = fields[i + 1] as string;
  }

  const type = map.type ?? 'unknown';
  let payload: unknown = {};
  try {
    payload = map.data ? JSON.parse(map.data) : {};
  } catch {
    payload = {};
  }

  switch (type) {
    case 'cart.checked_out':
      logger.info({ cartId: map.cartId, version: map.version, payload }, 'pedido cerrado');
      break;
    case 'cart.merged':
      logger.info({ cartId: map.cartId, payload }, 'carrito fusionado tras el login');
      break;
    case 'cart.item_added':
    case 'cart.item_removed':
    case 'cart.item_updated':
    case 'cart.created':
    case 'cart.cleared':
    case 'cart.promo_applied':
    case 'cart.promo_removed':
      logger.debug({ type, cartId: map.cartId, payload }, 'evento de carrito');
      break;
    default:
      logger.warn({ type, cartId: map.cartId }, 'evento desconocido');
  }

  await redis.xack(STREAM, GROUP, id);
}

async function loop(): Promise<void> {
  while (running) {
    try {
      await reclaimPending();
      const response = (await redis.xreadgroup(
        'GROUP',
        GROUP,
        CONSUMER,
        'COUNT',
        config.worker.batchSize,
        'BLOCK',
        config.worker.blockMs,
        'STREAMS',
        STREAM,
        '>',
      )) as Array<[string, Array<[string, string[]]>]> | null;

      if (!response) continue;
      for (const [, entries] of response) {
        for (const [id, fields] of entries) {
          await handle(id, fields);
        }
      }
    } catch (err) {
      if (!running) break;
      logger.error({ err }, 'error en el bucle del worker');
      await new Promise((resolve) => setTimeout(resolve, 1_000));
    }
  }
}

await ensureGroup();
logger.info({ stream: STREAM, group: GROUP, consumer: CONSUMER }, 'worker iniciado');

const stop = async (signal: string): Promise<void> => {
  logger.info({ signal }, 'apagando el worker');
  running = false;
  try {
    await redis.quit();
  } catch {
    redis.disconnect();
  }
  process.exit(0);
};

process.on('SIGTERM', () => void stop('SIGTERM'));
process.on('SIGINT', () => void stop('SIGINT'));

await loop();

