import type Redis from 'ioredis';

export interface ConsumerEvent {
  id: string;
  type: string;
  cartId: string;
  version: string;
  occurredAt: string;
  actorId: string;
  data: Record<string, unknown>;
}

export interface EventConsumerOptions {
  /** Nombre lógico del stream (sin prefijo). */
  stream: string;
  group: string;
  consumer: string;
  batchSize: number;
  blockMs: number;
  /** Tiempo de inactividad tras el cual un mensaje se puede reclamar. */
  minIdleMs: number;
  /** Prefijo físico de claves (ioredis no lo aplica a XGROUP). */
  keyPrefix: string;
}

/**
 * Consumidor de eventos sobre Redis Streams con grupo de consumidores.
 *
 * Varios workers pueden consumir en paralelo (el grupo reparte los mensajes)
 * y los mensajes de un worker caído se recuperan con XAUTOCLAIM.
 */
export class EventConsumer {
  private readonly redis: Redis;
  private readonly options: EventConsumerOptions;

  constructor(redis: Redis, options: EventConsumerOptions) {
    this.redis = redis;
    this.options = options;
  }

  /**
   * Clave física del stream. `ioredis` conoce la posición de la clave en
   * XREADGROUP/XAUTOCLAIM (y la aplica), pero no en XGROUP, por lo que ahí
   * hay que pasar la clave ya prefijada.
   */
  physicalStreamKey(): string {
    return `${this.options.keyPrefix}${this.options.stream}`;
  }

  async ensureGroup(): Promise<boolean> {
    try {
      await this.redis.xgroup(
        'CREATE',
        this.physicalStreamKey(),
        this.options.group,
        '0',
        'MKSTREAM',
      );
      return true;
    } catch (err) {
      if (err instanceof Error && err.message.includes('BUSYGROUP')) return false;
      throw err;
    }
  }

  /** Recupera mensajes huérfanos de consumidores que han muerto. */
  async reclaimPending(): Promise<ConsumerEvent[]> {
    const result = (await this.redis.xautoclaim(
      this.options.stream,
      this.options.group,
      this.options.consumer,
      this.options.minIdleMs,
      '0-0',
      'COUNT',
      this.options.batchSize,
    )) as unknown as [string, Array<[string, string[]]>];

    const entries = result?.[1] ?? [];
    return entries.map(([id, fields]) => this.toEvent(id, fields));
  }

  async readBatch(): Promise<ConsumerEvent[]> {
    const response = (await this.redis.xreadgroup(
      'GROUP',
      this.options.group,
      this.options.consumer,
      'COUNT',
      this.options.batchSize,
      'BLOCK',
      this.options.blockMs,
      'STREAMS',
      this.options.stream,
      '>',
    )) as Array<[string, Array<[string, string[]]>]> | null;

    if (!response) return [];
    const events: ConsumerEvent[] = [];
    for (const [, entries] of response) {
      for (const [id, fields] of entries) {
        events.push(this.toEvent(id, fields));
      }
    }
    return events;
  }

  async ack(id: string): Promise<void> {
    await this.redis.xack(this.options.stream, this.options.group, id);
  }

  private toEvent(id: string, fields: string[]): ConsumerEvent {
    const map: Record<string, string> = {};
    for (let i = 0; i < fields.length; i += 2) {
      map[fields[i] as string] = fields[i + 1] as string;
    }
    let data: Record<string, unknown> = {};
    try {
      data = map.data ? (JSON.parse(map.data) as Record<string, unknown>) : {};
    } catch {
      data = {};
    }
    return {
      id,
      type: map.type ?? 'unknown',
      cartId: map.cartId ?? '',
      version: map.version ?? '0',
      occurredAt: map.occurredAt ?? '',
      actorId: map.actorId ?? '',
      data,
    };
  }
}

import { loadConfig } from './config.js';
import { createLogger } from './bootstrap.js';
import { EventConsumer, type ConsumerEvent } from './infrastructure/event-consumer.js';
import { createRedisClient } from './infrastructure/redis.js';

/**
 * Consumidor de eventos del carrito.
 *
 * Lee el stream de Redis con un grupo de consumidores: varios workers pueden
 * procesar en paralelo repartiendo los mensajes, y si uno cae, sus mensajes
 * pendientes se recuperan con XAUTOCLAIM. Esto permite escalar el
 * procesamiento de forma independiente de la API.
 */
const config = loadConfig();
const logger = createLogger(config);
const redis = createRedisClient(config, 'worker');

const consumer = new EventConsumer(redis, {
  stream: 'events:cart',
  group: config.worker.consumerGroup,
  consumer: `${config.worker.consumerName}-${process.pid}`,
  batchSize: config.worker.batchSize,
  blockMs: config.worker.blockMs,
  minIdleMs: 30_000,
  keyPrefix: config.redis.keyPrefix,
});

let running = true;

function logEvent(event: ConsumerEvent): void {
  switch (event.type) {
    case 'cart.checked_out':
      logger.info(
        { cartId: event.cartId, version: event.version, payload: event.data },
        'pedido cerrado',
      );
      break;
    case 'cart.merged':
      logger.info(
        { cartId: event.cartId, payload: event.data },
        'carrito fusionado tras el login',
      );
      break;
    case 'cart.created':
    case 'cart.item_added':
    case 'cart.item_removed':
    case 'cart.item_updated':
    case 'cart.cleared':
    case 'cart.promo_applied':
    case 'cart.promo_removed':
      logger.debug({ type: event.type, cartId: event.cartId, payload: event.data }, 'evento de carrito');
      break;
    default:
      logger.warn({ type: event.type, cartId: event.cartId }, 'evento desconocido');
  }
}

async function handle(event: ConsumerEvent): Promise<void> {
  logEvent(event);
  await consumer.ack(event.id);
}

async function loop(): Promise<void> {
  while (running) {
    try {
      const reclaimed = await consumer.reclaimPending();
      for (const event of reclaimed) await handle(event);

      const events = await consumer.readBatch();
      for (const event of events) await handle(event);
    } catch (err) {
      if (!running) break;
      logger.error({ err }, 'error en el bucle del worker');
      await new Promise((resolve) => setTimeout(resolve, 1_000));
    }
  }
}

const created = await consumer.ensureGroup();
logger.info(
  {
    stream: 'events:cart',
    group: config.worker.consumerGroup,
    consumer: `${config.worker.consumerName}-${process.pid}`,
    created,
  },
  'worker iniciado',
);

const stop = async (signal: string): Promise<void> => {
  logger.info({ signal }, 'apagando el worker');
  running = false;
  try {
    await redis.quit();
  } catch {
    redis.disconnect();
  }
  process.exit(0);
};

process.on('SIGTERM', () => void stop('SIGTERM'));
process.on('SIGINT', () => void stop('SIGINT'));

await loop();

import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { createTestApp, type TestApp } from '../helpers/test-app.js';
import { EventConsumer } from '../../src/infrastructure/event-consumer.js';
import { RedisEventPublisher } from '../../src/infrastructure/redis-event-publisher.js';

let harness: TestApp;

describe('consumidor de eventos (grupo de consumidores)', () => {
  beforeAll(async () => {
    harness = await createTestApp();
  });

  afterAll(async () => {
    await harness.close();
  });

  it('crea el grupo en la clave correcta y consume los eventos emitidos', async () => {
    const group = `grupo-${randomUUID().slice(0, 8)}`;
    const consumer = new EventConsumer(harness.redis, {
      stream: 'events:cart',
      group,
      consumer: 'test-consumer',
      batchSize: 10,
      blockMs: 200,
      minIdleMs: 30_000,
      keyPrefix: harness.config.redis.keyPrefix,
    });

    const created = await consumer.ensureGroup();
    expect(created).toBe(true);

    // el grupo debe existir sobre la clave física (con prefijo)
    const info = await harness.redis.xinfo('GROUPS', 'events:cart');
    expect(Array.isArray(info)).toBe(true);
    const groups = info as Array<[string, unknown]>;
    expect(groups.some(([name]) => name === group)).toBe(true);

    // se emite un evento desde la API (outbox transaccional)
    const cart = await harness.app.inject({
      method: 'POST',
      url: '/v1/carts',
      headers: { 'x-session-id': 'sesion-consumer' },
      payload: {},
    });
    const cartId = cart.json().id as string;

    const publisher = new RedisEventPublisher(harness.redis, 'events:cart');
    await publisher.publish({
      id: randomUUID(),
      type: 'cart.viewed',
      occurredAt: new Date().toISOString(),
      cartId,
      version: 1,
      actorId: null,
      payload: { origen: 'test' },
    });

    const events = await consumer.readBatch();
    expect(events.length).toBeGreaterThan(0);

    const viewed = events.find((e) => e.type === 'cart.viewed');
    expect(viewed).toBeDefined();
    expect(viewed?.cartId).toBe(cartId);
    expect(viewed?.data).toMatchObject({ origen: 'test' });

    await consumer.ack(viewed!.id);

    // el evento de creación (outbox) también debe estar en el stream
    const created2 = events.find((e) => e.type === 'cart.created');
    expect(created2).toBeDefined();
    expect(created2?.version).toBe('1');
  });

  it('reclama mensajes pendientes de un consumidor muerto', async () => {
    const group = `grupo-${randomUUID().slice(0, 8)}`;
    const options = {
      stream: 'events:cart',
      group,
      batchSize: 10,
      blockMs: 200,
      minIdleMs: 10,
      keyPrefix: harness.config.redis.keyPrefix,
    };

    const dead = new EventConsumer(harness.redis, { ...options, consumer: 'muere' });
    await dead.ensureGroup();

    const publisher = new RedisEventPublisher(harness.redis, 'events:cart');
    await publisher.publish({
      id: randomUUID(),
      type: 'cart.created',
      occurredAt: new Date().toISOString(),
      cartId: 'cart-pendiente',
      version: 3,
      actorId: null,
      payload: {},
    });

    // el consumidor muerto no llega a confirmar el mensaje
    await dead.readBatch();

    const rescuer = new EventConsumer(harness.redis, { ...options, consumer: 'rescata' });
    await new Promise((resolve) => setTimeout(resolve, 30));
    const reclaimed = await rescuer.reclaimPending();
    expect(reclaimed.length).toBeGreaterThan(0);
    expect(reclaimed[0]?.cartId).toBe('cart-pendiente');
  });
});

