async groups(): Promise<string[]> {
  const info = (await this.redis.xinfo('GROUPS', this.physicalStreamKey())) as unknown as
    | unknown[]
    | null;
  if (!Array.isArray(info)) return [];
  // XINFO devuelve una lista plana: ['name', <grupo>, 'consumers', 0, ...]
  const names: string[] = [];
  for (let i = 0; i < info.length - 1; i += 1) {
    if (info[i] === 'name' && typeof info[i + 1] === 'string') {
      names.push(info[i + 1] as string);
    }
  }
  return names;
}

